   BREADCRUMB
   ──────────────────────────────────────────────────── */
.single-person__breadcrumb {
    background-color: var(--color-neutral-800);
    border-block-end: var(--border-width-thin) solid rgba(255, 255, 255, 0.06);
    /* padding-top absorve a altura do header fixo (182px) + espaçamento interno (12px) */
    padding-block-start: calc(var(--header-height, 182px) + var(--spacing-3));
    padding-block-end: var(--spacing-3);           /* 12px */
}

.single-person__breadcrumb-list {
    display: grid;
    grid-auto-flow: column;
    grid-auto-columns: max-content;
    align-items: center;
    gap: var(--spacing-2);                         /* 8px */
